/// Split a module into its leading MODULE doc-comment and the rest.
///
/// A module doc-comment is the contiguous run of comment lines at the very top that is FOLLOWED BY A
/// BLANK LINE — the blank is what marks the run as documenting the module rather than the first
/// declaration. A comment run sitting directly on a declaration (no blank) is that declaration's OWN
/// doc-comment: `head` comes back empty and the import block lands ABOVE it. That is the anti-swallow
/// rule — the emitter never wedges imports between a doc-comment and the thing it documents. Any blank
/// separator is consumed, so re-joining through [`crate::imports_fmt::layout`] restores exactly one blank instead of
/// piling them up.
pub fn split_head(code: &str) -> (&str, &str) {
    let mut comment_end = 0usize;
    let mut saw_comment = false;
    for line in code.split_inclusive('\n') {
        let t = line.trim_start();
        if t.starts_with("//") || t.starts_with("/*") || t.starts_with('*') {
            comment_end += line.len();
            saw_comment = true;
        } else {
            break;
        }
    }
    if !saw_comment {
        return ("", code);
    }
    let rest = &code[comment_end..];
    let body = rest.trim_start_matches(['\n', '\r']);
    if body.len() == rest.len() {
        // no blank separated the comment from what follows ⇒ it is a symbol doc-comment, not a
        // module header. Leave the whole thing as body; the block goes above it.
        ("", code)
    } else {
        (&code[..comment_end], body)
    }
}
